// Generated by tools/sr71/build-ivsi.mjs from measured source dial ticks and original quaternions.
// Browser-only piecewise calibration, not recovered SRFT148/MSFS dynamics.
export const SR71_IVSI_ANCHORS=Object.freeze([[-6000,-0.4696048965109052],[-4000,-0.3501604002532295],[-2000,-0.22492119967361168],[-1000,-0.1465771932415154],[0,0.0030779928054792682],[1000,0.15298503610799183],[2000,0.2326928545128734],[4000,0.3573813610021],[6000,0.47653360749935897]].map(Object.freeze));
export function ivsiPose(verticalMps){
 if(!Number.isFinite(verticalMps))return undefined;
 const fpm=Math.min(6000,Math.max(-6000,verticalMps*60/.3048)),a=SR71_IVSI_ANCHORS;
 let i=1;while(i<a.length-1&&fpm>a[i][0])i++;
 const [lo,hi]=[a[i-1],a[i]],u=lo[1]+(hi[1]-lo[1])*(fpm-lo[0])/(hi[0]-lo[0]);
 return ((u%1)+1)%1;
}
